begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4231,"word":"exhilaration","meaning":"興奮","example":"The successful launch filled the students with exhilaration.","example_zh":"成功發射讓學生興奮不已。","original_meaning":"興奮","original_example":"A feeling of exhilaration.","original_example_zh":"一種振奮的感覺。"},{"source_id":4232,"word":"expatriation","meaning":"移居國外","example":"Her memoir described the challenges of expatriation and building a new home abroad.","example_zh":"她的回憶錄描寫移居國外與建立新家的挑戰。","original_meaning":"移居國外","original_example":"Voluntary expatriation.","original_example_zh":"自願移居海外。"},{"source_id":4233,"word":"experimentation","meaning":"實驗","example":"Careful experimentation helped us choose the strongest bridge design.","example_zh":"仔細實驗幫助我們選出最堅固的橋梁設計。","original_meaning":"實驗","original_example":"Scientific experimentation.","original_example_zh":"科學實驗。"},{"source_id":4234,"word":"expropriation","meaning":"徵收","example":"The exhibit examined the expropriation of land for a railway.","example_zh":"展覽探討興建鐵路時的土地徵收。","original_meaning":"徵收","original_example":"Land expropriation.","original_example_zh":"徵收土地。"},{"source_id":4235,"word":"extermination","meaning":"消滅","example":"The garden plan called for the extermination of invasive weeds.","example_zh":"花園計畫要求徹底清除入侵雜草。","original_meaning":"消滅","original_example":"Pest extermination.","original_example_zh":"害蟲防治。"},{"source_id":4236,"word":"extravagance","meaning":"奢侈","example":"The enormous unused banquet revealed the ruler's extravagance.","example_zh":"龐大而無人享用的宴席顯露統治者的奢侈。","original_meaning":"奢侈","original_example":"Avoid extravagance.","original_example_zh":"避免奢侈。"},{"source_id":4237,"word":"extremist","meaning":"極端分子","example":"The novel portrayed an extremist who refused any compromise.","example_zh":"小說描寫一個拒絕任何妥協的極端分子。","original_meaning":"極端分子","original_example":"Political extremists.","original_example_zh":"政治極端分子。"},{"source_id":4238,"word":"faculty","meaning":"教職員","example":"The faculty met to discuss improvements to the school library.","example_zh":"教職員開會討論改善學校圖書館。","original_meaning":"教職員","original_example":"The university faculty.","original_example_zh":"大學教職員。"},{"source_id":4239,"word":"fallible","meaning":"易犯錯的","example":"The fallible narrator sometimes misunderstood what other characters meant.","example_zh":"這位可能犯錯的敘事者，有時誤解其他角色的意思。","original_meaning":"易犯錯的","original_example":"Humans are fallible.","original_example_zh":"人非聖賢，孰能無過。"},{"source_id":4240,"word":"fanatic","meaning":"狂熱者","example":"The chess fanatic spent every break studying new openings.","example_zh":"那位西洋棋狂熱者每次休息都研究新開局。","original_meaning":"狂熱者","original_example":"A religious fanatic.","original_example_zh":"一位宗教狂熱分子。"},{"source_id":4241,"word":"fascism","meaning":"法西斯主義","example":"The museum examined the rise of fascism and its suppression of dissent.","example_zh":"博物館探討法西斯主義的興起及其對異議的壓制。","original_meaning":"法西斯","original_example":"The rise of fascism.","original_example_zh":"法西斯主義的崛起。"},{"source_id":4242,"word":"fatality","meaning":"死亡事故；死亡者","example":"The report recorded one fatality in the mining accident.","example_zh":"報告記錄礦難造成一人死亡。","original_meaning":"死亡事故","original_example":"Traffic fatalities.","original_example_zh":"交通死亡事故。"},{"source_id":4243,"word":"feat","meaning":"壯舉","example":"Completing the huge model by hand was an impressive feat.","example_zh":"徒手完成巨大模型，是令人敬佩的壯舉。","original_meaning":"壯舉","original_example":"An incredible feat.","original_example_zh":"一項不可思議的壯舉。"},{"source_id":4244,"word":"feudal","meaning":"封建的","example":"The history model showed the relationships within a feudal society.","example_zh":"歷史模型展示封建社會中的關係。","original_meaning":"封建的","original_example":"A feudal system.","original_example_zh":"封建制度。"},{"source_id":4245,"word":"figurative","meaning":"比喻的","example":"The phrase used figurative language to compare hope with a growing seed.","example_zh":"那個片語以比喻語言，把希望比作成長的種子。","original_meaning":"比喻的","original_example":"Figurative language.","original_example_zh":"修辭手法。"},{"source_id":4246,"word":"filament","meaning":"細絲；燈絲","example":"The old light bulb had a thin filament inside its glass shell.","example_zh":"舊燈泡的玻璃外殼裡有一條細燈絲。","original_meaning":"細絲","original_example":"A light filament.","original_example_zh":"燈絲。"},{"source_id":4247,"word":"fixture","meaning":"固定裝置","example":"The wall lamp was a permanent fixture in the old library.","example_zh":"壁燈是老圖書館的固定裝置。","original_meaning":"固定裝置","original_example":"Light fixtures.","original_example_zh":"燈具。"},{"source_id":4248,"word":"flagrant","meaning":"公然的","example":"Leaving rubbish in the protected garden was a flagrant violation of the rules.","example_zh":"在保護花園亂丟垃圾，公然違反規定。","original_meaning":"公然的","original_example":"A flagrant violation.","original_example_zh":"公然違反。"},{"source_id":4249,"word":"flammable","meaning":"易燃的","example":"The technician stored the flammable materials in a special safety cabinet.","example_zh":"技術人員把易燃材料收進專用安全櫃。","original_meaning":"易燃的","original_example":"Flammable materials.","original_example_zh":"易燃材料。"},{"source_id":4250,"word":"flex","meaning":"彎曲","example":"She could flex the thin branch without breaking it.","example_zh":"她能彎曲細樹枝而不折斷。","original_meaning":"彎曲","original_example":"Flex your muscles.","original_example_zh":"展示你的肌肉。"},{"source_id":4251,"word":"foothold","meaning":"立足點","example":"The climber found a secure foothold on the practice wall.","example_zh":"攀登者在練習牆找到穩固落腳點。","original_meaning":"立足點","original_example":"Gain a foothold.","original_example_zh":"站穩腳跟。"},{"source_id":4252,"word":"foray","meaning":"嘗試；初次涉足","example":"The exhibition was her first foray into sculpture.","example_zh":"這場展覽是她初次嘗試雕塑。","original_meaning":"嘗試","original_example":"A foray into politics.","original_example_zh":"涉足政壇。"},{"source_id":4253,"word":"foreclose","meaning":"取消抵押品贖回權；對抵押財產行使權利","example":"The novel described a bank preparing to foreclose on an unpaid mortgage.","example_zh":"小說描寫銀行準備對未清償的抵押貸款行使抵押權。","original_meaning":"喪失抵押品贖回權","original_example":"Foreclose a mortgage.","original_example_zh":"沒收抵押貸款。"},{"source_id":4254,"word":"forensic","meaning":"法醫的；鑑識的","example":"The forensic expert compared the two fingerprints.","example_zh":"鑑識專家比較兩枚指紋。","original_meaning":"法醫的","original_example":"Forensic evidence.","original_example_zh":"法醫證據。"},{"source_id":4255,"word":"fortify","meaning":"加固","example":"The builders added braces to fortify the wooden tower.","example_zh":"建造者加裝支架，加固木塔。","original_meaning":"加固","original_example":"Fortify the walls.","original_example_zh":"加固城牆。"},{"source_id":4256,"word":"fragile","meaning":"脆弱的","example":"The fragile vase needed careful packing.","example_zh":"脆弱花瓶需要小心包裝。","original_meaning":"脆弱的","original_example":"A fragile ecosystem.","original_example_zh":"一個脆弱的生態系統。"},{"source_id":4257,"word":"fraternity","meaning":"兄弟會","example":"The university fraternity organized a community cleanup.","example_zh":"大學兄弟會舉辦社區清潔活動。","original_meaning":"兄弟會","original_example":"A college fraternity.","original_example_zh":"一個大學兄弟會。"},{"source_id":4258,"word":"freelancer","meaning":"自由工作者","example":"The freelancer illustrated books for several publishers.","example_zh":"自由工作者為數家出版社繪製插圖。","original_meaning":"自由工作者","original_example":"Work as a freelancer.","original_example_zh":"以自由工作者身分工作。"},{"source_id":4259,"word":"frugal","meaning":"節儉的","example":"Her frugal habits helped the club save money for new books.","example_zh":"她節儉的習慣幫社團存錢買新書。","original_meaning":"節儉的","original_example":"A frugal lifestyle.","original_example_zh":"節儉的生活方式。"},{"source_id":4260,"word":"fumble","meaning":"摸索","example":"He began to fumble with the unfamiliar clasp on the case.","example_zh":"他不熟悉琴盒扣環，開始笨拙摸索。","original_meaning":"摸索","original_example":"Fumble for keys.","original_example_zh":"摸索鑰匙。"},{"source_id":4261,"word":"fungi","meaning":"真菌","example":"The nature guide pointed out fungi growing on a fallen log.","example_zh":"自然導覽員指出倒木上生長的真菌。","original_meaning":"真菌","original_example":"Fungi and bacteria.","original_example_zh":"真菌與細菌。"},{"source_id":4262,"word":"furnace","meaning":"熔爐","example":"The metalworker inspected the furnace through a protected viewing window.","example_zh":"金屬工匠透過防護觀察窗檢查熔爐。","original_meaning":"熔爐","original_example":"A blast furnace.","original_example_zh":"一座高爐。"},{"source_id":4263,"word":"gallop","meaning":"飛馳","example":"The horse began to gallop across the open field.","example_zh":"那匹馬開始在開闊草地飛馳。","original_meaning":"飛馳","original_example":"The horse galloped.","original_example_zh":"那匹馬疾馳而去。"},{"source_id":4264,"word":"genetic","meaning":"基因的","example":"The genetic model helped students understand inherited traits.","example_zh":"基因模型幫助學生理解遺傳特徵。","original_meaning":"基因的","original_example":"Genetic engineering.","original_example_zh":"基因工程。"},{"source_id":4265,"word":"geopolitics","meaning":"地緣政治","example":"The geopolitics seminar examined the importance of the narrow sea route.","example_zh":"地緣政治研討會探討狹窄海上航道的重要性。","original_meaning":"地緣政治","original_example":"International geopolitics.","original_example_zh":"國際地緣政治。"},{"source_id":4266,"word":"geriatric","meaning":"老年的；老年醫學的","example":"The hospital opened a geriatric care unit for older patients.","example_zh":"醫院開設照顧高齡病人的老年照護病房。","original_meaning":"老年的","original_example":"Geriatric care.","original_example_zh":"老年照護。"},{"source_id":4267,"word":"germ","meaning":"病菌","example":"The health exhibit used a model to represent a disease-causing germ.","example_zh":"健康展覽用模型呈現會致病的病菌。","original_meaning":"病菌","original_example":"Kill germs.","original_example_zh":"殺死病菌。"},{"source_id":4268,"word":"ghetto","meaning":"隔離居住區；貧民區","example":"The museum documented life in the ghetto under wartime persecution.","example_zh":"博物館記錄戰時迫害下隔離居住區的生活。","original_meaning":"貧民區","original_example":"An urban ghetto.","original_example_zh":"一個城市貧民窟。"},{"source_id":4269,"word":"glamour","meaning":"魅力","example":"The theatre's old photographs recalled the glamour of opening nights.","example_zh":"劇院老照片喚起首演夜的華麗魅力。","original_meaning":"魅力","original_example":"Hollywood glamour.","original_example_zh":"好萊塢的魅力。"},{"source_id":4270,"word":"gorge","meaning":"峽谷","example":"The river flowed through a deep gorge below the viewpoint.","example_zh":"河流穿過觀景點下方深峽谷。","original_meaning":"峽谷","original_example":"A deep gorge.","original_example_zh":"一道深谷。"},{"source_id":4271,"word":"granite","meaning":"花崗岩","example":"The sculptor selected a block of granite for the monument.","example_zh":"雕塑家選一塊花崗岩製作紀念碑。","original_meaning":"花崗岩","original_example":"A granite surface.","original_example_zh":"花崗岩表面。"},{"source_id":4272,"word":"gratitude","meaning":"感恩","example":"The students expressed gratitude to the volunteers who repaired the library.","example_zh":"學生向修復圖書館的志工表達感恩。","original_meaning":"感恩","original_example":"Express gratitude.","original_example_zh":"表達感激之情。"},{"source_id":4273,"word":"grim","meaning":"嚴峻的","example":"The grim report described extensive damage to the village after the storm.","example_zh":"嚴峻報告描述風暴後村莊受損廣泛。","original_meaning":"嚴峻的","original_example":"A grim situation.","original_example_zh":"嚴峻的局面。"},{"source_id":4274,"word":"groundwater","meaning":"地下水","example":"The model showed groundwater beneath the surface of the land.","example_zh":"模型展示地表下的地下水。","original_meaning":"地下水","original_example":"Groundwater pollution.","original_example_zh":"地下水污染。"},{"source_id":4275,"word":"grudge","meaning":"怨恨","example":"He let go of his grudge after his friend sincerely apologized.","example_zh":"朋友誠懇道歉後，他放下怨恨。","original_meaning":"怨恨","original_example":"Hold a grudge.","original_example_zh":"心懷怨恨。"},{"source_id":4276,"word":"handout","meaning":"講義","example":"The teacher gave each student a handout with a diagram of the river.","example_zh":"老師發給每位學生一份含河流圖的講義。","original_meaning":"講義","original_example":"Distribute handouts.","original_example_zh":"分發傳單。"},{"source_id":4277,"word":"harbour","meaning":"港灣","example":"The fishing boats returned to the sheltered harbour before the storm.","example_zh":"風暴前，漁船返回有遮蔽的港灣。","original_meaning":"港灣","original_example":"A natural harbour.","original_example_zh":"天然港灣。"},{"source_id":4278,"word":"hardship","meaning":"困苦","example":"The family endured hardship while rebuilding their home.","example_zh":"家庭重建家園時承受困苦。","original_meaning":"困苦","original_example":"Endure hardship.","original_example_zh":"忍受艱辛。"},{"source_id":4279,"word":"harness","meaning":"利用","example":"The model turbine could harness the energy of flowing water.","example_zh":"模型渦輪能利用流水能量。","original_meaning":"利用","original_example":"Harness solar energy.","original_example_zh":"利用太陽能。"},{"source_id":4280,"word":"haven","meaning":"避風港","example":"The quiet garden became a haven for people seeking rest.","example_zh":"安靜花園成為尋求休息者的避風港。","original_meaning":"避風港","original_example":"A tax haven.","original_example_zh":"避稅天堂。"},{"source_id":4281,"word":"heir","meaning":"繼承人","example":"The heir agreed to preserve the family's historic house.","example_zh":"繼承人同意保存家族歷史住宅。","original_meaning":"繼承人","original_example":"The heir to the throne.","original_example_zh":"王位繼承人。"},{"source_id":4282,"word":"hemorrhage","meaning":"出血","example":"The medical lecture explained how a hemorrhage can cause blood loss.","example_zh":"醫學講座解說出血如何造成血液流失。","original_meaning":"出血","original_example":"Internal hemorrhage.","original_example_zh":"內出血。"},{"source_id":4283,"word":"herbivore","meaning":"草食動物","example":"The exhibit described the deer as a herbivore.","example_zh":"展覽把鹿介紹為草食動物。","original_meaning":"草食動物","original_example":"Cows are herbivores.","original_example_zh":"牛是草食動物。"},{"source_id":4284,"word":"heresy","meaning":"異端","example":"The history lesson examined how an idea came to be condemned as heresy.","example_zh":"歷史課探討某種觀念如何被譴責為異端。","original_meaning":"異端","original_example":"Accused of heresy.","original_example_zh":"被指控為異端。"},{"source_id":4285,"word":"hindsight","meaning":"後見之明","example":"With hindsight, we realized that the first design needed another support.","example_zh":"事後回看，我們才明白第一版設計需要多一根支架。","original_meaning":"後見之明","original_example":"In hindsight.","original_example_zh":"事後看來。"},{"source_id":4286,"word":"homicide","meaning":"殺人","example":"The documentary examined the investigation of a homicide.","example_zh":"紀錄片探討一宗殺人案的調查。","original_meaning":"殺人","original_example":"Investigate a homicide.","original_example_zh":"調查一宗謀殺案。"},{"source_id":4287,"word":"hospice","meaning":"安寧病房","example":"The hospice provided a peaceful place for patients and their families.","example_zh":"安寧病房為病人與家人提供平靜空間。","original_meaning":"安寧病房","original_example":"End of life hospice.","original_example_zh":"臨終安寧療護。"},{"source_id":4288,"word":"hostility","meaning":"敵意","example":"The mediator helped reduce hostility between the two groups.","example_zh":"調解人協助減輕兩個群體之間的敵意。","original_meaning":"敵意","original_example":"Show hostility.","original_example_zh":"表現出敵意。"},{"source_id":4289,"word":"humiliation","meaning":"羞辱","example":"The teacher stopped the teasing to protect the student from humiliation.","example_zh":"老師制止取笑，避免學生受辱。","original_meaning":"羞辱","original_example":"Public humiliation.","original_example_zh":"公開羞辱。"},{"source_id":4290,"word":"hybrid","meaning":"混合；混合體","example":"The new design was a hybrid of a greenhouse and a reading room.","example_zh":"新設計融合溫室與閱讀室。","original_meaning":"混合","original_example":"A hybrid vehicle.","original_example_zh":"一輛混合動力車。"},{"source_id":4291,"word":"hypocrite","meaning":"偽君子","example":"The story's hypocrite demanded honesty while secretly cheating.","example_zh":"故事中的偽君子要求別人誠實，自己卻暗中作弊。","original_meaning":"偽君子","original_example":"He is a hypocrite.","original_example_zh":"他是個偽君子。"},{"source_id":4292,"word":"icon","meaning":"圖標；偶像","example":"The small book icon opened the reading section.","example_zh":"小書本圖標可以開啟閱讀區。","original_meaning":"圖標；偶像","original_example":"A cultural icon.","original_example_zh":"一位文化偶像。"},{"source_id":4293,"word":"idealism","meaning":"理想主義","example":"Her idealism inspired the team to create a library open to everyone.","example_zh":"她的理想主義鼓舞團隊建立向所有人開放的圖書館。","original_meaning":"理想主義","original_example":"Political idealism.","original_example_zh":"政治理想主義。"},{"source_id":4294,"word":"insolvency","meaning":"破產；無力償債","example":"The report explained how the company's debts led to insolvency.","example_zh":"報告說明公司債務如何導致無力償債。","original_meaning":"破產","original_example":"Face insolvency.","original_example_zh":"面臨破產。"},{"source_id":4295,"word":"invasion","meaning":"入侵","example":"The museum traced the invasion of the island by a foreign army.","example_zh":"博物館追溯外國軍隊入侵島嶼的歷史。","original_meaning":"入侵","original_example":"A military invasion.","original_example_zh":"軍事入侵。"},{"source_id":4296,"word":"kindergarten","meaning":"幼稚園","example":"The high-school volunteers read picture books at the kindergarten.","example_zh":"高中志工在幼稚園為幼兒讀繪本。","original_meaning":"幼稚園","original_example":"Start kindergarten.","original_example_zh":"開始上幼兒園。"},{"source_id":4297,"word":"locomotive","meaning":"火車頭","example":"The restored locomotive stood at the railway museum.","example_zh":"修復的火車頭陳列在鐵道博物館。","original_meaning":"火車頭","original_example":"A steam locomotive.","original_example_zh":"蒸汽火車。"},{"source_id":4298,"word":"philosopher","meaning":"哲學家","example":"The philosopher asked the students what makes an action fair.","example_zh":"哲學家問學生，什麼讓一個行為公平。","original_meaning":"哲學家","original_example":"A Greek philosopher.","original_example_zh":"一位希臘哲學家。"},{"source_id":4299,"word":"predominantly","meaning":"主要地","example":"The hillside was predominantly covered with pine trees.","example_zh":"山坡主要被松樹覆蓋。","original_meaning":"主要地","original_example":"A predominantly rural area.","original_example_zh":"一個以農村為主的地區。"},{"source_id":4300,"word":"subordinate","meaning":"下屬的","example":"The diagram showed a subordinate office reporting to the central department.","example_zh":"圖表顯示下屬辦公室向中央部門報告的關係。","original_meaning":"下屬的","original_example":"A subordinate position.","original_example_zh":"從屬地位。"},{"source_id":4301,"word":"taboo","meaning":"禁忌","example":"The novel challenged a taboo against discussing family disagreements.","example_zh":"小說挑戰不許談論家庭分歧的禁忌。","original_meaning":"禁忌","original_example":"A social taboo.","original_example_zh":"社會禁忌。"},{"source_id":4302,"word":"tactic","meaning":"戰術","example":"The team's tactic was to control the center of the chessboard.","example_zh":"棋隊的戰術是控制棋盤中央。","original_meaning":"戰術","original_example":"A clever tactic.","original_example_zh":"高明的策略。"},{"source_id":4303,"word":"tamper","meaning":"竄改；擅動","example":"The curator warned visitors not to tamper with the display case.","example_zh":"策展人提醒訪客不要擅動展示櫃。","original_meaning":"竄改","original_example":"Tamper with evidence.","original_example_zh":"篡改證據。"},{"source_id":4304,"word":"tangle","meaning":"纏繞","example":"The loose strings began to tangle inside the box.","example_zh":"鬆散細繩開始在盒內纏繞。","original_meaning":"纏繞","original_example":"Tangled wires.","original_example_zh":"纏結的電線。"},{"source_id":4305,"word":"tardy","meaning":"遲緩的；遲到的","example":"The tardy student arrived after the opening discussion had begun.","example_zh":"遲到的學生在開場討論開始後才抵達。","original_meaning":"遲緩的","original_example":"A tardy response.","original_example_zh":"遲緩的反應。"},{"source_id":4306,"word":"tarnish","meaning":"損壞名聲","example":"The false claim could tarnish the museum's reputation.","example_zh":"不實說法可能損害博物館名聲。","original_meaning":"損壞名聲","original_example":"Tarnish reputation.","original_example_zh":"損毀聲譽。"},{"source_id":4307,"word":"tedium","meaning":"單調","example":"The music helped relieve the tedium of sorting hundreds of cards.","example_zh":"音樂幫忙減輕整理數百張卡片的單調。","original_meaning":"單調","original_example":"The tedium of routine.","original_example_zh":"例行公事的乏味。"},{"source_id":4308,"word":"temperance","meaning":"節制","example":"She practiced temperance by taking only what she needed at the buffet.","example_zh":"她在自助餐只取所需食物，展現節制。","original_meaning":"節制","original_example":"Practice temperance.","original_example_zh":"節制行事。"},{"source_id":4309,"word":"tempo","meaning":"節奏；速度","example":"The conductor asked the musicians to slow the tempo.","example_zh":"指揮請樂手放慢速度。","original_meaning":"節奏","original_example":"A fast tempo.","original_example_zh":"快速的節奏。"},{"source_id":4310,"word":"tender","meaning":"溫柔的","example":"She gave the frightened puppy a tender touch.","example_zh":"她溫柔輕撫受驚小狗。","original_meaning":"溫柔的","original_example":"A tender smile.","original_example_zh":"溫柔的微笑。"},{"source_id":4311,"word":"tenure","meaning":"任期","example":"During her tenure as principal, the school built a new library.","example_zh":"她擔任校長期間，學校興建新圖書館。","original_meaning":"任期","original_example":"A long tenure.","original_example_zh":"漫長的任期。"},{"source_id":4312,"word":"terminal","meaning":"航廈；終點站","example":"The travelers waited in the airport terminal before boarding.","example_zh":"旅客登機前在機場航廈等候。","original_meaning":"航廈；終點站","original_example":"We took the airport shuttle from Terminal Two to the hotel.","original_example_zh":"我們從第二航廈搭機場接駁車前往飯店。"},{"source_id":4313,"word":"texture","meaning":"質地","example":"The rough texture of the bark contrasted with the smooth stone.","example_zh":"樹皮粗糙質地與光滑石頭形成對比。","original_meaning":"質地","original_example":"A smooth texture.","original_example_zh":"光滑的質地。"},{"source_id":4314,"word":"theorem","meaning":"定理","example":"The teacher used a geometric model to explain the theorem.","example_zh":"老師用幾何模型解釋定理。","original_meaning":"定理","original_example":"A mathematical theorem.","original_example_zh":"一個數學定理。"},{"source_id":4315,"word":"thermometer","meaning":"溫度計","example":"The students used a thermometer to measure the water's temperature.","example_zh":"學生用溫度計測量水溫。","original_meaning":"溫度計","original_example":"Read the thermometer.","original_example_zh":"讀取溫度計。"},{"source_id":4316,"word":"thrive","meaning":"蓬勃發展","example":"The seedlings began to thrive in the sunny garden.","example_zh":"幼苗在陽光充足的花園開始茁壯。","original_meaning":"蓬勃發展","original_example":"The business thrives.","original_example_zh":"事業蒸蒸日上。"},{"source_id":4317,"word":"timber","meaning":"木材","example":"The carpenter selected dry timber for the new shelves.","example_zh":"木匠挑選乾燥木材製作新書架。","original_meaning":"木材","original_example":"Timber industry.","original_example_zh":"木材業。"},{"source_id":4318,"word":"tissue","meaning":"組織","example":"The microscope revealed the structure of the plant tissue.","example_zh":"顯微鏡顯示植物組織的構造。","original_meaning":"組織","original_example":"Muscle tissue.","original_example_zh":"肌肉組織。"},{"source_id":4319,"word":"tobacco","meaning":"菸草","example":"The museum displayed dried tobacco leaves as part of its agricultural history exhibit.","example_zh":"博物館在農業史展覽展示乾燥菸草葉。","original_meaning":"菸草","original_example":"Tobacco use.","original_example_zh":"菸草使用。"},{"source_id":4320,"word":"tolerance","meaning":"容忍","example":"The club encouraged tolerance of different opinions.","example_zh":"社團鼓勵包容不同意見。","original_meaning":"容忍","original_example":"Religious tolerance.","original_example_zh":"宗教寬容。"},{"source_id":4321,"word":"topography","meaning":"地形學；地形","example":"The map's topography showed steep hills and a narrow valley.","example_zh":"地圖呈現陡峭山丘與狹窄山谷的地形。","original_meaning":"地形學","original_example":"Study topography.","original_example_zh":"研究地形。"},{"source_id":4322,"word":"torment","meaning":"折磨","example":"The character's guilt became a source of constant torment.","example_zh":"那個角色的罪惡感成為持續的精神折磨。","original_meaning":"折磨","original_example":"In torment.","original_example_zh":"備受折磨。"},{"source_id":4323,"word":"torpedo","meaning":"魚雷","example":"The naval museum displayed a deactivated torpedo in a sealed exhibit.","example_zh":"海軍博物館在封閉展區展示停用魚雷。","original_meaning":"魚雷","original_example":"Launch a torpedo.","original_example_zh":"發射魚雷。"},{"source_id":4324,"word":"torrential","meaning":"傾盆的","example":"Torrential rain kept the visitors inside the shelter.","example_zh":"傾盆大雨讓訪客留在遮蔽處。","original_meaning":"傾盆的","original_example":"Torrential rain.","original_example_zh":"傾盆大雨。"},{"source_id":4325,"word":"totalitarianism","meaning":"極權主義","example":"The lesson examined how totalitarianism restricts independent thought.","example_zh":"課程探討極權主義如何限制獨立思考。","original_meaning":"極權主義","original_example":"Fight totalitarianism.","original_example_zh":"對抗極權主義。"},{"source_id":4326,"word":"tourism","meaning":"觀光業","example":"Responsible tourism helped support the village's museum and craft shops.","example_zh":"負責任的觀光支持村莊博物館與工藝店。","original_meaning":"觀光業","original_example":"Promote tourism.","original_example_zh":"推廣觀光。"},{"source_id":4327,"word":"toxic","meaning":"有毒的","example":"The laboratory kept the toxic samples in sealed containers.","example_zh":"實驗室把有毒樣本保存在密封容器。","original_meaning":"有毒的","original_example":"Toxic chemicals.","original_example_zh":"有毒化學物質。"},{"source_id":4328,"word":"trait","meaning":"特質","example":"Patience was a trait that made her a helpful mentor.","example_zh":"耐心這項特質讓她成為樂於助人的導師。","original_meaning":"特質","original_example":"A positive trait.","original_example_zh":"一種積極的特質。"},{"source_id":4329,"word":"transitional","meaning":"過渡性的","example":"The temporary classroom served a transitional purpose during the renovation.","example_zh":"翻新期間，臨時教室提供過渡用途。","original_meaning":"過渡性的","original_example":"A transitional period.","original_example_zh":"一個過渡時期。"},{"source_id":4330,"word":"transmission","meaning":"傳輸","example":"The exhibit demonstrated the transmission of sound through a simple device.","example_zh":"展覽透過簡單裝置示範聲音傳輸。","original_meaning":"傳輸","original_example":"Data transmission.","original_example_zh":"資料傳輸。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-exhilaration-01-v1","level":"senior","word":"exhilaration","sort_order":1,"sense":"興奮","alt_zh":"高中生與成年老師在校園安全區看小型水火箭升空後歡喜擊掌，無製作步驟。","example":"The successful launch filled the students with exhilaration.","example_zh":"成功發射讓學生興奮不已。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exhilaration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-expatriation-01-v1","level":"senior","word":"expatriation","sort_order":1,"sense":"移居國外","alt_zh":"成年女性在新居整理行李與原鄉家人照片，窗外是陌生城市，氣氛溫暖。","example":"Her memoir described the challenges of expatriation and building a new home abroad.","example_zh":"她的回憶錄描寫移居國外與建立新家的挑戰。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/expatriation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-experimentation-01-v1","level":"senior","word":"experimentation","sort_order":1,"sense":"實驗","alt_zh":"高中生在老師旁對比幾座木模型橋的安全小砝碼負重測試。","example":"Careful experimentation helped us choose the strongest bridge design.","example_zh":"仔細實驗幫助我們選出最堅固的橋梁設計。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/experimentation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-expropriation-01-v1","level":"senior","word":"expropriation","sort_order":1,"sense":"徵收","alt_zh":"高中生在歷史博物館觀察村莊地圖與鐵路路線模型，成年導覽員客觀解說。","example":"The exhibit examined the expropriation of land for a railway.","example_zh":"展覽探討興建鐵路時的土地徵收。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/expropriation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-extermination-01-v1","level":"senior","word":"extermination","sort_order":1,"sense":"消滅","alt_zh":"成年園丁與高中志工戴手套連根清除入侵雜草，分類收集，無藥劑或動物傷害。","example":"The garden plan called for the extermination of invasive weeds.","example_zh":"花園計畫要求徹底清除入侵雜草。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/extermination-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-extravagance-01-v1","level":"senior","word":"extravagance","sort_order":1,"sense":"奢侈","alt_zh":"虛構歷史宮廷擺著過量精緻食物與華麗器皿，成年官員看著浪費場景，無文字。","example":"The enormous unused banquet revealed the ruler's extravagance.","example_zh":"龐大而無人享用的宴席顯露統治者的奢侈。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/extravagance-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-extremist-01-v1","level":"senior","word":"extremist","sort_order":1,"sense":"極端分子","alt_zh":"高中生閱讀虛構政治小說，插畫中成年人物固執拒聽圓桌其他意見，無武器宣傳符號。","example":"The novel portrayed an extremist who refused any compromise.","example_zh":"小說描寫一個拒絕任何妥協的極端分子。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/extremist-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-faculty-01-v1","level":"senior","word":"faculty","sort_order":1,"sense":"教職員","alt_zh":"多位成年教師在會議桌前討論圖書館模型與學生閱讀需求。","example":"The faculty met to discuss improvements to the school library.","example_zh":"教職員開會討論改善學校圖書館。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/faculty-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fallible-01-v1","level":"senior","word":"fallible","sort_order":1,"sense":"易犯錯的","alt_zh":"高中文學小組在老師旁比較故事圖卡的不同角色觀點，文字不可辨識。","example":"The fallible narrator sometimes misunderstood what other characters meant.","example_zh":"這位可能犯錯的敘事者，有時誤解其他角色的意思。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fallible-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fanatic-01-v1","level":"senior","word":"fanatic","sort_order":1,"sense":"狂熱者","alt_zh":"高中棋迷在校園休息時間專注研究棋盤與棋譜，同學友善靠近。","example":"The chess fanatic spent every break studying new openings.","example_zh":"那位西洋棋狂熱者每次休息都研究新開局。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fanatic-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fascism-01-v1","level":"senior","word":"fascism","sort_order":1,"sense":"法西斯主義","alt_zh":"高中生在歷史博物館聽成年導覽員客觀介紹極權制度圖示與封存報紙，無仇恨標誌或暴力。","example":"The museum examined the rise of fascism and its suppression of dissent.","example_zh":"博物館探討法西斯主義的興起及其對異議的壓制。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fascism-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fatality-01-v1","level":"senior","word":"fatality","sort_order":1,"sense":"死亡事故；死亡者","alt_zh":"成年調查人員在礦業紀念館查看事故報告，旁邊放著礦工安全帽與花束，無遺體或傷害。","example":"The report recorded one fatality in the mining accident.","example_zh":"報告記錄礦難造成一人死亡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fatality-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-feat-01-v1","level":"senior","word":"feat","sort_order":1,"sense":"壯舉","alt_zh":"高中團隊與老師自豪欣賞剛完成的大型精細木橋模型，大家鼓掌。","example":"Completing the huge model by hand was an impressive feat.","example_zh":"徒手完成巨大模型，是令人敬佩的壯舉。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/feat-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-feudal-01-v1","level":"senior","word":"feudal","sort_order":1,"sense":"封建的","alt_zh":"高中生在博物館觀察虛構歷史城堡、農田與成年領主農民的微縮模型，無傷害。","example":"The history model showed the relationships within a feudal society.","example_zh":"歷史模型展示封建社會中的關係。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/feudal-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-figurative-01-v1","level":"senior","word":"figurative","sort_order":1,"sense":"比喻的","alt_zh":"高中文學課中老師展示幼苗插畫與詩集，學生思考比喻，無文字。","example":"The phrase used figurative language to compare hope with a growing seed.","example_zh":"那個片語以比喻語言，把希望比作成長的種子。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/figurative-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-filament-01-v1","level":"senior","word":"filament","sort_order":1,"sense":"細絲；燈絲","alt_zh":"高中生在成年老師旁觀察未通電透明舊燈泡，細緻金屬燈絲清楚可見。","example":"The old light bulb had a thin filament inside its glass shell.","example_zh":"舊燈泡的玻璃外殼裡有一條細燈絲。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/filament-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fixture-01-v1","level":"senior","word":"fixture","sort_order":1,"sense":"固定裝置","alt_zh":"高中訪客欣賞歷史圖書館牆上穩固安裝的金屬壁燈。","example":"The wall lamp was a permanent fixture in the old library.","example_zh":"壁燈是老圖書館的固定裝置。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fixture-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-flagrant-01-v1","level":"senior","word":"flagrant","sort_order":1,"sense":"公然的","alt_zh":"成年保育員與高中志工在公共花園看到座椅旁被丟棄的垃圾，露出不認同神情。","example":"Leaving rubbish in the protected garden was a flagrant violation of the rules.","example_zh":"在保護花園亂丟垃圾，公然違反規定。","image_url":"https://jb